25	func New(checkDatabase func(context.Context) error, service Service) http.Handler {
26		mux := http.NewServeMux()
27		mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
28			respond(w, http.StatusOK, `{"status":"ok"}`)
29		})
30		mux.HandleFunc("GET /readyz", func(w http.ResponseWriter, r *http.Request) {
31			ctx, cancel := context.WithTimeout(r.Context(), time.Second)
32			defer cancel()
33			if err := checkDatabase(ctx); err != nil {
34				respond(w, http.StatusServiceUnavailable, `{"status":"unavailable"}`)
35				return
36			}
37			respond(w, http.StatusOK, `{"status":"ready"}`)
38		})
39	
40		h := &handlers{service: service}
41		mux.HandleFunc("POST /entitlements", h.createEntitlement)
42		mux.HandleFunc("GET /entitlements/{entitlementID}", h.getEntitlement)
43		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations", h.createReservation)
44		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations/{reservationID}/confirm", h.settle(entitlements.ActionConfirm))
45		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations/{reservationID}/release", h.settle(entitlements.ActionRelease))
46		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations/{reservationID}/reverse", h.reverseReservation)
47		mux.HandleFunc("POST /entitlements/{entitlementID}/adjustments", h.createAdjustment)
48		mux.HandleFunc("POST /entitlements/{entitlementID}/reschedules", h.createReschedule)
49		mux.HandleFunc("POST /entitlements/{entitlementID}/seat-adjustments", h.createSeatAdjustment)
50		return mux
51	}
