69		}
70		validFrom, errFrom := time.Parse(time.RFC3339, req.ValidFrom)
71		validTo, errTo := time.Parse(time.RFC3339, req.ValidTo)
72		if req.ValidFrom == "" || req.ValidTo == "" || errFrom != nil || errTo != nil {
73			respondError(w, &entitlements.Error{
74				Code:    entitlements.CodeInvalidRequest,
75				Message: "valid_from and valid_to must be RFC 3339 timestamps, e.g. 2026-01-01T00:00:00Z",
76			})
77			return
78		}
79		ent, err := h.service.CreateEntitlement(r.Context(), entitlements.CreateEntitlementInput{
80			EntitlementID: req.EntitlementID,
81			SeatsTotal:    req.SeatsTotal,
82			QuotaTotal:    req.QuotaTotal,
83			ValidFrom:     validFrom,
84			ValidTo:       validTo,
85		})
86		if err != nil {
87			respondError(w, err)
88			return
89		}
90		respondJSON(w, http.StatusCreated, ent)
91	}
