14	func TestHealthAndReadiness(t *testing.T) {
15		for _, tc := range []struct {
16			name, method, path, body string
17			dbError                  error
18			status                   int
19			calls                    int
20		}{
21			{"liveness", "GET", "/healthz", "ok", errors.New("database offline"), 200, 0},
22			{"ready", "GET", "/readyz", "ready", nil, 200, 1},
23			{"unavailable", "GET", "/readyz", "unavailable", errors.New("private connection details"), 503, 1},
24			{"unknown path", "GET", "/nope", "404", nil, 404, 0},
25			{"wrong method", "POST", "/readyz", "Method Not Allowed", nil, 405, 0},
26		} {
27			t.Run(tc.name, func(t *testing.T) {
28				calls := 0
29				handler := New(func(ctx context.Context) error {
30					calls++
31					if _, ok := ctx.Deadline(); !ok {
32						t.Error("readiness database check must have a deadline")
33					}
34					return tc.dbError
35				}, nil)
36				response := httptest.NewRecorder()
37				handler.ServeHTTP(response, httptest.NewRequest(tc.method, tc.path, nil))
38				if response.Code != tc.status || !strings.Contains(response.Body.String(), tc.body) || calls != tc.calls {
39					t.Fatalf("status=%d body=%q database calls=%d", response.Code, response.Body.String(), calls)
40				}
41				if strings.Contains(response.Body.String(), "private connection details") {
42					t.Fatal("database error leaked into public response")
43				}
44			})
45		}
46	}
