216	func TestSeatAdjustmentRoute(t *testing.T) {
217		adjustment := entitlements.SeatAdjustment{
218			SeatAdjustmentID: "seat-1", Delta: 20, SeatTotal: 120, CreatedAt: time.Now(),
219		}
