221		created := serve(t, service, "POST", "/entitlements/ent-1/seat-adjustments",
222			`{"seat_adjustment_id":"seat-1","delta":20}`)
223		if created.Code != 201 || service.adjustmentID != "seat-1" || service.delta != 20 {
224			t.Fatalf("new seat adjustment: status=%d id=%q delta=%d body=%q",
225				created.Code, service.adjustmentID, service.delta, created.Body.String())
226		}
227		if !strings.Contains(created.Body.String(), `"seat_total":120`) ||
228			!strings.Contains(created.Body.String(), `"seat_adjustment_id":"seat-1"`) {
229			t.Fatalf("seat adjustment body: %q", created.Body.String())
230		}
231		service.created = false
232		replayed := serve(t, service, "POST", "/entitlements/ent-1/seat-adjustments",
233			`{"seat_adjustment_id":"seat-1","delta":20}`)
234		if replayed.Code != 200 {
235			t.Fatalf("replayed seat adjustment: status=%d body=%q", replayed.Code, replayed.Body.String())
236		}
237		// A missing or zero delta, unknown fields and malformed JSON are rejected
238		// before the domain is called; a missing identifier reaches the domain.
239		for _, body := range []string{
240			`{"seat_adjustment_id":"seat-1"}`,
241			`{"seat_adjustment_id":"seat-1","delta":0}`,
242			`{"seat_adjustment_id":"seat-1","delta":20,"amount":5}`,
243			`{`,
244		} {
245			response := serve(t, service, "POST", "/entitlements/ent-1/seat-adjustments", body)
246			if response.Code != 400 || !strings.Contains(response.Body.String(), `"invalid_request"`) {
247				t.Fatalf("body %q: status=%d body=%q", body, response.Code, response.Body.String())
248			}
249		}
250		invalid := &fakeService{err: &entitlements.Error{Code: entitlements.CodeInvalidRequest, Message: "bad seat_adjustment_id"}}
251		response := serve(t, invalid, "POST", "/entitlements/ent-1/seat-adjustments", `{"delta":20}`)
252		if response.Code != 400 || !strings.Contains(response.Body.String(), `"invalid_request"`) {
253			t.Fatalf("missing seat_adjustment_id: status=%d body=%q", response.Code, response.Body.String())
254		}
255		// Domain failures keep their stable status and envelope.
256		for _, tc := range []struct {
257			code string
258			want int
259		}{
260			{entitlements.CodeEntitlementNotFound, 404},
261			{entitlements.CodeSeatAdjustmentChanged, 409},
262			{entitlements.CodeInsufficientQuota, 422},
263		} {
264			failing := &fakeService{err: &entitlements.Error{Code: tc.code, Message: "boom"}}
265			response := serve(t, failing, "POST", "/entitlements/ent-1/seat-adjustments",
266				`{"seat_adjustment_id":"seat-1","delta":-100}`)
267			if response.Code != tc.want || !strings.Contains(response.Body.String(), `"`+tc.code+`"`) {
268				t.Fatalf("code %q: status=%d body=%q", tc.code, response.Code, response.Body.String())
269			}
270		}
271	}
