func TestRescheduleRoute(t *testing.T) {
	reschedule := entitlements.Reschedule{
		RescheduleID: "move-1",
		NewValidFrom: time.Date(2026, 2, 1, 0, 0, 0, 0, time.UTC),
		NewValidTo:   time.Date(2027, 2, 1, 0, 0, 0, 0, time.UTC),
