1131	func TestConcurrentReschedulesRewriteOnce(t *testing.T) {
1132		store := testStore(t)
1133		from, to := activeWindow()
1134		id := uniqueID(t)
1135		mustCreate(t, store, id, 100, from, to)
1136		ctx := context.Background()
1137		newFrom := time.Now().Add(-time.Hour).UTC().Truncate(time.Microsecond)
1138		newTo := time.Now().Add(2 * time.Hour).UTC().Truncate(time.Microsecond)
1139	
1140		// Many workers submit the same reschedule identifier and also hammer the
1141		// entitlement with quota operations; all serialize on the row lock.
1142		const workers = 8
1143		var wg sync.WaitGroup
1144		errs := make(chan error, workers*4)
1145		for w := 0; w < workers; w++ {
1146			wg.Add(1)
1147			go func(w int) {
1148				defer wg.Done()
1149				if _, _, err := store.RescheduleEntitlement(ctx, id, "move-1", newFrom, newTo); err != nil {
1150					errs <- err
1151				}
1152				if _, _, err := store.RescheduleEntitlement(ctx, id, "move-1", newFrom, newTo); err != nil {
1153					errs <- err
1154				}
1155				rid := fmt.Sprintf("res-%d", w)
1156				if _, _, err := store.CreateReservation(ctx, id, rid, "dept-1", 5); err != nil {
1157					errs <- err
1158					return
1159				}
1160				_, _ = store.SettleReservation(ctx, id, rid, ActionConfirm)
1161			}(w)
1162		}
1163		wg.Wait()
1164		close(errs)
1165		for err := range errs {
1166			t.Fatalf("unexpected concurrent failure: %v", err)
1167		}
1168		view, err := store.GetView(ctx, id)
1169		if err != nil {
1170			t.Fatalf("view: %v", err)
1171		}
1172		if len(view.Reschedules) != 1 || !view.ValidFrom.Equal(newFrom) || !view.ValidTo.Equal(newTo) {
1173			t.Fatalf("reschedule applied more than once: %+v", view)
1174		}
1175		if view.UsedAmount != workers*5 || view.QuotaTotal != 100 ||
1176			view.AvailableAmount != 100-view.UsedAmount {
1177			t.Fatalf("quota state after concurrent reschedules: %+v", view)
1178		}
1179	}
