1396	func TestSeatAdjustmentsDoNotTouchQuota(t *testing.T) {
1397		store := testStore(t)
1398		id := createSeatEntitlement(t, store, 100, 200)
1399		ctx := context.Background()
1400	
1401		if _, _, err := store.CreateSeatAdjustment(ctx, id, "seat-up", 50); err != nil {
1402			t.Fatalf("seat increase: %v", err)
1403		}
1404		if _, _, err := store.CreateReservation(ctx, id, "res-1", "dept-a", 180); err != nil {
1405			t.Fatalf("reserve: %v", err)
1406		}
1407		// A quota adjustment moves quota only.
1408		if _, _, err := store.CreateAdjustment(ctx, id, "quota-up", 100, time.Now().Add(-time.Minute)); err != nil {
1409			t.Fatalf("quota increase: %v", err)
1410		}
1411		// Releasing the hold frees seat occupancy; a seat recovery then moves
1412		// seats only.
1413		if _, err := store.SettleReservation(ctx, id, "res-1", ActionRelease); err != nil {
1414			t.Fatalf("release: %v", err)
1415		}
1416		if _, _, err := store.CreateSeatAdjustment(ctx, id, "seat-down", -140); err != nil {
1417			t.Fatalf("seat decrease: %v", err)
1418		}
1419	
1420		view, err := store.GetView(ctx, id)
1421		if err != nil {
1422			t.Fatalf("view: %v", err)
1423		}
1424		if view.SeatsTotal != 10 {
1425			t.Fatalf("seats should end at 10: %+v", view)
1426		}
1427		if view.QuotaTotal != 300 || view.UsedAmount != 0 || view.ReservedAmount != 0 ||
1428			view.AvailableAmount != 300 {
1429			t.Fatalf("seat adjustments altered quota figures: %+v", view)
1430		}
1431	}
