1433	func TestReservationDepartmentIsStoredAndImmutable(t *testing.T) {
1434		store := testStore(t)
1435		from, to := activeWindow()
1436		id := uniqueID(t)
1437		mustCreate(t, store, id, 100, from, to)
1438		ctx := context.Background()
1439	
1440		created, made, err := store.CreateReservation(ctx, id, "res-1", "dept-a", 30)
1441		if err != nil || !made || created.DepartmentID != "dept-a" {
1442			t.Fatalf("create with department: %+v created=%v err=%v", created, made, err)
1443		}
1444		// Replay with the same department returns the original.
1445		replay, made, err := store.CreateReservation(ctx, id, "res-1", "dept-a", 30)
1446		if err != nil || made || replay.DepartmentID != "dept-a" {
1447			t.Fatalf("replay: %+v created=%v err=%v", replay, made, err)
1448		}
1449		// The department is an immutable reservation attribute.
1450		_, _, err = store.CreateReservation(ctx, id, "res-1", "dept-b", 30)
1451		wantCode(t, err, CodeReservationParamChanged)
1452		// A missing department is invalid input.
1453		_, _, err = store.CreateReservation(ctx, id, "res-2", "", 10)
1454		wantCode(t, err, CodeInvalidRequest)
1455	
1456		view, _ := store.GetView(ctx, id)
1457		if len(view.Reservations) != 1 || view.Reservations[0].DepartmentID != "dept-a" {
1458			t.Fatalf("department not preserved in view: %+v", view.Reservations)
1459		}
1460		if view.ReservedAmount != 30 {
1461			t.Fatalf("failed calls changed state: %+v", view)
1462		}
