1465	func TestConcurrentSeatAdjustmentsApplyOnce(t *testing.T) {
1466		store := testStore(t)
1467		id := createSeatEntitlement(t, store, 1000, 1000)
1468		ctx := context.Background()
1469	
1470		const workers = 8
1471		var wg sync.WaitGroup
1472		results := make(chan error, workers*3)
1473		for w := 0; w < workers; w++ {
1474			wg.Add(1)
1475			go func(w int) {
1476				defer wg.Done()
1477				sid := fmt.Sprintf("seat-%d", w)
1478				// Each worker submits one increase, replays it, then submits a
1479				// decrease; replays and first submissions race across workers.
1480				_, _, err := store.CreateSeatAdjustment(ctx, id, sid, 5)
1481				results <- err
1482				_, _, err = store.CreateSeatAdjustment(ctx, id, sid, 5)
1483				results <- err
1484				_, _, err = store.CreateSeatAdjustment(ctx, id, fmt.Sprintf("seat-back-%d", w), -2)
1485				results <- err
1486			}(w)
1487		}
1488		wg.Wait()
1489		close(results)
1490		for err := range results {
1491			if err != nil {
1492				t.Fatalf("unexpected concurrent failure: %v", err)
1493			}
1494		}
1495		view, err := store.GetView(ctx, id)
1496		if err != nil {
1497			t.Fatalf("view: %v", err)
1498		}
1499		if view.SeatsTotal != 1000+workers*3 || len(view.SeatAdjustments) != workers*2 {
1500			t.Fatalf("concurrent seat adjustments broke state: %+v", view)
1501		}
1502		var summed int64
1503		for _, sa := range view.SeatAdjustments {
1504			summed += sa.Delta
1505		}
1506		if summed != workers*3 || view.SeatsTotal != 1000+summed {
1507			t.Fatalf("cumulative totals inconsistent: %+v", view)
1508		}
1509	}
