1511	func TestConcurrentSeatAdjustmentsAndReservations(t *testing.T) {
1512		store := testStore(t)
1513		id := createSeatEntitlement(t, store, 1000, 5000)
1514		ctx := context.Background()
1515	
1516		const workers = 8
1517		var wg sync.WaitGroup
1518		errs := make(chan error, workers*4)
1519		for w := 0; w < workers; w++ {
1520			wg.Add(1)
1521			go func(w int) {
1522				defer wg.Done()
1523				rid := fmt.Sprintf("res-%d", w)
1524				if _, _, err := store.CreateReservation(ctx, id, rid, "dept-a", 5); err != nil {
1525					errs <- err
1526					return
1527				}
1528				// Seat allocations and recoveries interleave with reservation
1529				// lifecycle operations on the same row lock.
1530				if _, _, err := store.CreateSeatAdjustment(ctx, id, fmt.Sprintf("seat-up-%d", w), 10); err != nil {
1531					errs <- err
1532				}
1533				if w%2 == 0 {
1534					_, _ = store.SettleReservation(ctx, id, rid, ActionConfirm)
1535				} else {
1536					_, _ = store.SettleReservation(ctx, id, rid, ActionRelease)
1537				}
1538				// 5 seats per worker stay allocated when confirmed, so recovering
1539				// the 10 just added per worker is always feasible.
1540				if _, _, err := store.CreateSeatAdjustment(ctx, id, fmt.Sprintf("seat-down-%d", w), -10); err != nil {
1541					errs <- err
1542				}
1543			}(w)
1544		}
1545		wg.Wait()
1546		close(errs)
1547		for err := range errs {
1548			t.Fatalf("unexpected concurrent failure: %v", err)
1549		}
1550		view, err := store.GetView(ctx, id)
1551		if err != nil {
1552			t.Fatalf("view: %v", err)
1553		}
1554		var allocated int64
1555		for _, r := range view.Reservations {
1556			if r.Status != StatusReleased {
1557				allocated += r.Amount
1558			}
1559		}
1560		if view.SeatsTotal != 1000 || view.SeatsTotal < allocated {
1561			t.Fatalf("seat invariant violated: seats=%d allocated=%d view=%+v",
1562				view.SeatsTotal, allocated, view)
1563		}
1564	}
1565	
1566	func TestSeatAdjustmentsSurviveReconnection(t *testing.T) {
1567		store := testStore(t)
1568		id := createSeatEntitlement(t, store, 100, 100)
1569		ctx := context.Background()
1570		if _, _, err := store.CreateSeatAdjustment(ctx, id, "seat-1", 50); err != nil {
1571			t.Fatalf("seat increase: %v", err)
1572		}
1573		if _, _, err := store.CreateSeatAdjustment(ctx, id, "seat-2", -20); err != nil {
1574			t.Fatalf("seat decrease: %v", err)
1575		}
1576		if _, _, err := store.CreateReservation(ctx, id, "res-1", "dept-a", 30); err != nil {
1577			t.Fatalf("reserve: %v", err)
1578		}
1579	
1580		// A fresh pool over the same database simulates a service restart.
1581		pool, err := pgxpool.New(ctx, os.Getenv("TEST_DATABASE_URL"))
1582		if err != nil {
1583			t.Fatalf("reconnect: %v", err)
1584		}
1585		defer pool.Close()
1586		restarted := NewStore(pool)
1587		view, err := restarted.GetView(ctx, id)
1588		if err != nil {
1589			t.Fatalf("view after restart: %v", err)
1590		}
1591		if view.SeatsTotal != 130 || len(view.SeatAdjustments) != 2 {
1592			t.Fatalf("seat state lost across restart: %+v", view)
1593		}
1594		if view.SeatAdjustments[0].SeatTotal != 150 || view.SeatAdjustments[1].SeatTotal != 130 {
1595			t.Fatalf("cumulative totals lost across restart: %+v", view.SeatAdjustments)
1596		}
1597		if len(view.Reservations) != 1 || view.Reservations[0].DepartmentID != "dept-a" {
1598			t.Fatalf("department lost across restart: %+v", view.Reservations)
1599		}
1600		// The identifier is still replayed, not re-applied; the allocation floor
1601		// still protects departments after the restart.
1602		replay, created, err := restarted.CreateSeatAdjustment(ctx, id, "seat-2", -20)
1603		if err != nil || created || replay.SeatTotal != 130 {
1604			t.Fatalf("seat adjustment replay after restart: %+v created=%v err=%v", replay, created, err)
1605		}
1606		_, _, err = restarted.CreateSeatAdjustment(ctx, id, "seat-crowd", -101)
1607		wantCode(t, err, CodeInsufficientQuota)
1608	}
