func closeIfDue(ctx context.Context, tx pgx.Tx, ent *entitlementRow, entitlementID string) error {
	if ent.closed() {
		return nil
	}
	if ent.now.Before(ent.validTo) {
		// Open and still within its window: fold in adjustments that came
		// due, exactly as the pre-closure flows always did.
		return applyDueAdjustments(ctx, tx, ent, entitlementID)
	}
	// Due adjustments are folded in first (an increase always applies; a
	// blocked decrease stays pending) so the snapshot records the in-force
	// quota total at the closure moment.
	if err := applyDueAdjustments(ctx, tx, ent, entitlementID); err != nil {
		return err
	}
	reserved, err := pendingAmount(ctx, tx, entitlementID)

