	enterTo := now.Add(time.Hour).UTC().Truncate(time.Microsecond)
	if _, _, err := store.RescheduleEntitlement(ctx, id, "move-enter", enterFrom, enterTo); err != nil {
		t.Fatalf("reschedule into window: %v", err)
	}
